<span class="line">    <span class="token class-name">String</span> jsonData <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Gson</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toJson</span><span class="token punctuation">(</span>reqData<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
